func init() {
	RegisterFile("_modules.yaml", loadModulesFile)
	RegisterHandTable("modules", loadModulesTable)
}

// loadModulesFile loads the generated `_modules.yaml`, strictly.
func loadModulesFile(reg *Registry, path string, data []byte) error {
	var doc ModulesDoc
	if len(bytes.TrimSpace(data)) > 0 {
		dec := yaml.NewDecoder(bytes.NewReader(data))
		dec.KnownFields(true) // a generated file with an unknown field was not written by modules --scan
		if err := dec.Decode(&doc); err != nil {
			return invalidf(path, "%v", err)
		}
	}
	if err := ValidateModulesDoc(doc); err != nil {
		return invalidf(path, "%v", err)
	}
	m := ModulesOf(reg)
	m.committed, m.doc, m.idx = true, doc, nil
	return nil
}

// loadModulesTable decodes a hand file's `modules:` block,
// `{<name>: {paths: [<glob>…]}}`. Modules are flat: a declaration carries
// `paths` and nothing else, so a nested `submodules:` or `children:` — or any
// other key — is refused.
func loadModulesTable(reg *Registry, path string, node *yaml.Node) error {
	if node.Kind != yaml.MappingNode {
		return invalidf(path, "modules: not a mapping")
	}
	m := ModulesOf(reg)
	for i := 0; i+1 < len(node.Content); i += 2 {
		name, val := node.Content[i].Value, node.Content[i+1]
		if err := checkModuleName(name); err != nil {
			return invalidf(path, "modules: %v", err)
		}
		if val.Kind != yaml.MappingNode {
			return invalidf(path, "modules: %s: not a mapping", name)
		}
		var globs stringList
		for j := 0; j+1 < len(val.Content); j += 2 {
			if key := val.Content[j].Value; key != "paths" {
				return invalidf(path, "modules: %s: unknown key %s (a module declares only paths; modules are flat)", name, key)
			}
			if err := val.Content[j+1].Decode(&globs); err != nil {
				return invalidf(path, "modules: %s: paths: %v", name, err)
			}
		}
		if len(globs) == 0 {
			return invalidf(path, "modules: %s: paths is required", name)
		}
		for _, g := range globs {
			if err := checkScopeGlob(g); err != nil {
				return invalidf(path, "modules: %s: %v", name, err)
			}
		}
		m.addHand(path, name, globs)
	}
	return nil
}

// --- ownership ---------------------------------------------------------------

// claimant is one module as ownership sees it.
type claimant struct {
	name, provider string
	rank           int
	root           string   // subtree and package providers
	globs          []string // hand and agent
	hand           *HandModule
	row            *ModuleRow
}

type modIndex struct {
	hand, agent []claimant
	subtree     map[string]map[string]claimant // provider → root → the smallest-named row there
	pkg         map[string][]claimant          // root → package rows
	collisions  []claimant                     // agent rows a hand module's name takes (dropped)
}

func (m *Modules) index() *modIndex {
	if m.idx != nil {
		return m.idx
	}
	ix := &modIndex{subtree: map[string]map[string]claimant{}, pkg: map[string][]claimant{}}
	for _, h := range m.Hand() {
		hm := m.hand[h.Name]
		ix.hand = append(ix.hand, claimant{name: h.Name, provider: ProviderHand, rank: 1, globs: hm.Globs, hand: hm})
	}
	for i := range m.doc.Modules {
		r := &m.doc.Modules[i]
		c := claimant{name: r.Name, provider: r.Provider, rank: providerRank[r.Provider], root: r.Root, globs: r.Paths, row: r}
		switch kindOf(r.Provider) {
		case kindGlob:
			if _, taken := m.hand[r.Name]; taken {
				ix.collisions = append(ix.collisions, c)
				continue
			}
			ix.agent = append(ix.agent, c)
		case kindSubtree:
			byRoot := ix.subtree[r.Provider]
			if byRoot == nil {
				byRoot = map[string]claimant{}
				ix.subtree[r.Provider] = byRoot
			}
			if prev, ok := byRoot[r.Root]; !ok || r.Name < prev.name {
				byRoot[r.Root] = c // equal roots: the smallest name claims (their sets are identical)
			}
		case kindPackage:
			ix.pkg[r.Root] = append(ix.pkg[r.Root], c)
		}
	}
	sort.Slice(ix.agent, func(i, j int) bool { return ix.agent[i].name < ix.agent[j].name })
	sort.Slice(ix.collisions, func(i, j int) bool { return ix.collisions[i].name < ix.collisions[j].name })
	m.idx = ix
	return ix
}

func matchGlobs(globs []string, p string) bool {
	for _, g := range globs {
		if ok, _ := doublestar.Match(g, p); ok {
			return true
		}
	}
	return false
}

// claims returns every module claiming p, best rank first: each hand and
// agent module whose globs match, the deepest codemap root, the deepest Gradle
// root, then the package whose directory holds p (by extension). Within one
// subtree provider only the deepest root claims — a parent never claims what
// a child covers.
func (ix *modIndex) claims(p string) []claimant {
	var out []claimant
	for _, c := range ix.hand {
		if matchGlobs(c.globs, p) {
			out = append(out, c)
		}
	}
	for _, c := range ix.agent {
		if matchGlobs(c.globs, p) {
			out = append(out, c)
		}
	}
	for _, prov := range []string{ProviderCodemap, ProviderGradle} {
		byRoot := ix.subtree[prov]
		if len(byRoot) == 0 {
			continue
		}
		for d := p; d != "." && d != "/" && d != ""; d = path.Dir(d) {
			if c, ok := byRoot[d]; ok {
				out = append(out, c)
				break
			}
		}
	}
	for _, c := range ix.pkg[path.Dir(p)] {
		if slices.Contains(packageExts[c.provider], path.Ext(p)) {
			out = append(out, c)
		}
	}
	return out
}

// overlap refuses two glob modules of one provider claiming p: two hand
// modules (an authoring error in the hand files) or two agent rows (the
// intake refuses those; a hand-edited table can still carry them).
func overlap(cs []claimant, p string) error {
	for i := 1; i < len(cs); i++ {
		a, b := cs[i-1], cs[i]
		if a.provider != b.provider || kindOf(a.provider) != kindGlob {
			continue
		}
		file := ModulesPath
		if b.hand != nil {
			file = b.hand.Files[0]
		}
		return invalidf(file, "modules: %s and %s both claim %s", a.name, b.name, p)
	}
	return nil
}

// OwnerOf returns the module owning path — the best-ranked claimant — or ""
// when no module claims it. It needs no file universe, so a consumer can ask
// about any path (a deleted one included). Two hand modules (or two agent
// rows) claiming path is an *InvalidError.
func (m *Modules) OwnerOf(p string) (string, error) {
	cs := m.index().claims(p)
	if err := overlap(cs, p); err != nil {
		return "", err
	}
	if len(cs) == 0 {
		return "", nil
	}
	return cs[0].name, nil
}

